import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { MapContainer, TileLayer, Marker, Popup } from 'react-leaflet';
import 'leaflet/dist/leaflet.css';

const API_URL = window.location.hostname === 'localhost'
    ? 'http://localhost:3001'
    : 'https://requena-backend-production.up.railway.app';

const AdminCheckins = () => {
    const [users, setUsers] = useState([]);
    const [expandedUser, setExpandedUser] = useState(null);
    const [checkinsMap, setCheckinsMap] = useState({});
    const navigate = useNavigate();

    useEffect(() => {
        fetchUsers();
    }, []);

    const fetchUsers = async () => {
        try {
            const response = await fetch(`${API_URL}/admin/users`);
            if (!response.ok) throw new Error('Error al cargar usuarios');
            const data = await response.json();
            setUsers(data);
        } catch (error) {
            console.error('Error al cargar usuarios:', error);
        }
    };

    const fetchCheckins = async (userId) => {
        if (expandedUser === userId) {
            setExpandedUser(null);
            return;
        }

        try {
            const response = await fetch(`${API_URL}/admin/user-checkins/${userId}`);
            if (!response.ok) throw new Error('Error al obtener historial de check-ins');
            const data = await response.json();
            setCheckinsMap(prev => ({ ...prev, [userId]: data }));
            setExpandedUser(userId);
        } catch (error) {
            console.error('Error al obtener historial de check-ins:', error);
        }
    };

    return (
        <div className="p-6 bg-gray-100 min-h-screen">
            <button className="mb-4 bg-gray-700 text-white px-4 py-2 rounded" onClick={() => navigate('/admin')}>
                Volver al Panel
            </button>
            <h1 className="text-3xl font-bold mb-6">Gestión de Check-ins y Check-outs</h1>

            <div className="bg-white shadow-lg rounded-lg p-4">
                <h2 className="text-xl font-semibold mb-4">Lista de Usuarios</h2>
                <table className="w-full">
                    <thead>
                    <tr className="bg-gray-200">
                        <th className="p-3">Nombre</th>
                        <th className="p-3">Correo</th>
                        <th className="p-3">Acciones</th>
                    </tr>
                    </thead>
                    <tbody>
                    {users.map((user) => (
                        <React.Fragment key={user.id}>
                            <tr className="border-b">
                                <td className="p-3">{user.name}</td>
                                <td className="p-3">{user.email}</td>
                                <td className="p-3">
                                    <button
                                        onClick={() => fetchCheckins(user.id)}
                                        className="bg-blue-500 text-white px-3 py-1 rounded hover:bg-blue-600"
                                    >
                                        {expandedUser === user.id ? 'Ocultar Historial' : 'Ver Historial'}
                                    </button>
                                </td>
                            </tr>
                            {expandedUser === user.id && (
                                <tr>
                                    <td colSpan="3" className="bg-gray-50 p-4">
                                        <h3 className="text-lg font-semibold mb-2">Historial de Check-ins y Check-outs</h3>
                                        {checkinsMap[user.id]?.length === 0 ? (
                                            <p>No hay registros para este usuario.</p>
                                        ) : (
                                            <>
                                                <table className="w-full text-sm mb-4">
                                                    <thead>
                                                    <tr className="bg-gray-200">
                                                        <th className="p-2">Fecha y Hora</th>
                                                        <th className="p-2">Tipo</th>
                                                        <th className="p-2">Ubicación</th>
                                                    </tr>
                                                    </thead>
                                                    <tbody>
                                                    {checkinsMap[user.id]?.map((c, idx) => (
                                                        <tr key={idx} className="border-b">
                                                            <td className="p-2">{new Date(c.timestamp).toLocaleString()}</td>
                                                            <td className="p-2">{c.type}</td>
                                                            <td className="p-2">{c.latitude}, {c.longitude}</td>
                                                        </tr>
                                                    ))}
                                                    </tbody>
                                                </table>

                                                <MapContainer center={[19.4326, -99.1332]} zoom={12} className="h-80 w-full">
                                                    <TileLayer url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png" />
                                                    {checkinsMap[user.id]?.map((c, index) => (
                                                        <Marker key={index} position={[c.latitude, c.longitude]}>
                                                            <Popup>
                                                                {c.type.toUpperCase()} - {new Date(c.timestamp).toLocaleString()}
                                                            </Popup>
                                                        </Marker>
                                                    ))}
                                                </MapContainer>
                                            </>
                                        )}
                                    </td>
                                </tr>
                            )}
                        </React.Fragment>
                    ))}
                    </tbody>
                </table>
            </div>
        </div>
    );
};

export default AdminCheckins;
